"""Render the static IPO dashboard."""
import html
import json
from datetime import date


def render_site(records, ai_endpoint="", market=None):
    today = date.today()
    def is_open(r):
        start, end = r.get('open_date'), r.get('close_date')
        return bool(start and end and start <= today <= end)
    opened = [r for r in records if is_open(r)]
    others = [r for r in records if not is_open(r)]
    def fmt(d):
        return d.strftime('%d %b') if d else '—'
    def table(group):
        rows = []
        for r in group:
            name = html.escape(r['name'])
            pct = r.get('gmp_pct')
            gmp = f'{pct:+.2f}%' if pct is not None else '—'
            ipo_type = 'Mainboard' if r.get('is_mainboard') else 'SME'
            rows.append(f'<tr><td>{name}</td><td>{ipo_type}</td><td class="green">{gmp}</td><td>{html.escape(str(r.get("price") or "—"))}</td><td>{html.escape(str(r.get("issue_size") or "—"))}</td><td>{fmt(r.get("open_date"))} – {fmt(r.get("close_date"))}</td><td>{fmt(r.get("listing_date"))}</td></tr>')
        return '<div class="scroll"><table><thead><tr><th>Company</th><th>Type</th><th>GMP</th><th>Price (₹)</th><th>Issue Size</th><th>Open – Close</th><th>Listing</th></tr></thead><tbody>' + (''.join(rows) or '<tr><td colspan="7">No IPOs in this view.</td></tr>') + '</tbody></table></div>'
    quotes = (market or {}).get('quotes', {})
    quote_cards = []
    for key, label, unit in (("nifty", "Nifty 50", "points"), ("sensex", "Sensex", "points"), ("gold", "Gold 999", "₹/10 g"), ("silver", "Silver 999", "₹/kg")):
        quote = quotes.get(key)
        if quote:
            value = f'{quote["value"]:,.2f}' if key in ("nifty", "sensex") else f'{quote["value"]:,.0f}'
            detail = quote.get('as_of') or f'Latest {quote.get("session", "")} rate'
            source = html.escape(quote['source'])
            url = html.escape(quote['url'], quote=True)
            quote_cards.append(f'<div class="market-card"><span>{label}</span><strong>{"₹" if key in ("gold", "silver") else ""}{value}</strong><small>{html.escape(unit)} · <a href="{url}" target="_blank" rel="noopener noreferrer">{source}</a></small><small>{html.escape(detail)}</small></div>')
        else:
            quote_cards.append(f'<div class="market-card"><span>{label}</span><strong>Unavailable</strong><small>Quote could not be fetched</small></div>')
    fetched = (market or {}).get('fetched_at', '')
    market_style = '''<style>.market-strip{margin-bottom:14px;padding:16px 20px;background:linear-gradient(100deg,#171e40,#121a38);border:1px solid #545c9b;border-radius:15px}.market-title{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:12px}.market-title h2{margin:0;font-size:1rem}.market-title small,.market-card small{color:#b9c1df;font-size:.72rem}.market-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.market-card{display:flex;flex-direction:column;gap:4px;padding:13px;background:#101936;border:1px solid #37436f;border-radius:10px}.market-card span{color:#c3c9e5;font-size:.82rem}.market-card strong{font-size:clamp(1.1rem,2vw,1.55rem);font-variant-numeric:tabular-nums}.market-card a{color:#a6bcff}@media(max-width:700px){.market-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.market-title{display:block}}</style>'''
    tooltip_style = '''<style>.info-wrap{display:inline-flex;position:relative;vertical-align:middle;margin-left:3px}.info-icon{display:inline-grid;place-items:center;width:17px;height:17px;padding:0;border:1px solid #9ca9db;border-radius:50%;background:#27345f;color:#e6eaff;font:bold 11px Georgia,serif;cursor:help}.info-icon:hover,.info-icon:focus-visible{background:#6c54b6;outline:2px solid #b9adff;outline-offset:2px}.info-tip{display:none;position:absolute;left:0;top:calc(100% + 7px);z-index:20;width:min(290px,80vw);padding:12px 14px;background:#eef0ff;color:#172044;border:1px solid #a5b1dd;border-radius:9px;box-shadow:0 10px 24px #0008;font-size:.8rem;font-weight:400;line-height:1.45;text-align:left;white-space:normal}.info-tip span{display:block;color:inherit}.info-tip span+span{margin-top:5px}.info-wrap:hover .info-tip,.info-wrap:focus-within .info-tip{display:block}.gauge .info-tip{left:auto;right:0}.detail-grid section{overflow:visible}@media(max-width:700px){.info-tip{left:auto;right:0}}</style>'''
    verdict_style = '''<style>.verdict{flex-wrap:wrap}.verdict .verdict-text{min-width:0;flex:1 1 210px}.verdict .gauge{width:165px}.verdict.watchlist{background:linear-gradient(110deg,#665019,#282f34)!important;border-color:#d9aa42!important}.verdict.watchlist .gauge-value{stroke:#ffd35a}.verdict.watchlist .gauge-score b{color:#ffe07c}.verdict.avoid{background:linear-gradient(110deg,#6b202b,#30253e)!important;border-color:#d36872!important}.verdict.avoid .gauge-value{stroke:#ff737e}.verdict.avoid .gauge-score b{color:#ff929b}.verdict .short-context{flex-basis:100%;margin-top:0;background:#101a2a88}</style>'''
    preferences_style = '''<style>.preferences{margin:0 0 18px;padding:15px;background:#101936;border:1px solid #3f4c7b;border-radius:11px}.preferences h3{margin:0 0 12px;font-size:1rem}.preference{margin:12px 0}.preference-head{display:flex;align-items:center;gap:5px}.preference-head output{margin-left:auto;color:#aaf1c2;font-weight:700}.preference input[type=range]{display:block;width:100%;margin:10px 0 4px;accent-color:#9e81f0}.preference-ends{display:flex;justify-content:space-between;gap:8px;color:#aab3d7;font-size:.72rem}.preferences .reset-preferences{padding:6px 11px;font-size:.78rem}.scored-for,.education-note{font-size:.78rem;color:#d8dfec;margin-top:9px}.weight-list{display:flex;flex-wrap:wrap;gap:5px 12px;margin-top:8px;color:#d8dfec;font-size:.75rem}.weight-list span{white-space:nowrap}.strengths-flags{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.strengths-flags section,.short-context{background:#151c3b;border:1px solid #454d82;border-radius:10px;padding:14px}.strengths-flags h3{font-size:.95rem;margin-bottom:8px}.strengths-flags ul{margin:0;padding-left:19px;font-size:.82rem;line-height:1.6}.short-context{margin-top:12px;font-size:.82rem}.short-context p{margin:5px 0}.short-notice{color:#ffe087}.strengths-flags [hidden],.short-context[hidden]{display:none}@media(max-width:700px){.strengths-flags{grid-template-columns:1fr}}</style>'''
    upload_style = '''<style>.upload-box a{color:#31217d;font-weight:700}.upload-box .button{white-space:nowrap;flex:none}.trend-subhead{font-size:.93rem;margin:22px 0 10px;color:#e6e6ff}.cashflow-legend{display:flex;justify-content:center;align-items:center;gap:7px;font-size:.78rem;color:#d8d8ef}.cashflow-legend span{display:inline-block;width:11px;height:11px;border-radius:3px}.cashflow-chart{display:block;width:100%;height:auto;margin-top:6px}</style>'''
    credit_html = '<div class="assignment-credit">Prepared by <strong>Tushar Mishra</strong> · M20A-25</div>'
    credit_style = '<style>.assignment-credit{text-align:right;color:#c6cbe5;font-size:.82rem;margin:0 2px 10px}.assignment-credit strong{color:#f7f6ff}</style>'
    market_html = market_style + tooltip_style + verdict_style + preferences_style + upload_style + credit_style + credit_html + f'<section class="market-strip" aria-label="Market snapshot"><div class="market-title"><h2>Market snapshot</h2><small>Fetched {html.escape(fetched.replace("T", " "))} IST · Quotes may be delayed</small></div><div class="market-grid">{"".join(quote_cards)}</div></section>'
    ipo_context_json = json.dumps([{'name': r['name'], 'gmp_pct': r.get('gmp_pct'), 'open_date': r.get('open_date').isoformat() if r.get('open_date') else None, 'close_date': r.get('close_date').isoformat() if r.get('close_date') else None} for r in records]).replace('<', '\\u003c')
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" type="image/png" href="favicon.png"><title>IPO Dashboard</title>
<style>
:root{{color-scheme:dark;font-family:Inter,Segoe UI,Arial,sans-serif;background:#090e25;color:#f5f4ff}}*{{box-sizing:border-box}}body{{margin:0 auto;padding:20px;max-width:1500px;background:radial-gradient(circle at 50% 0,#222d58,transparent 60%)}}h1{{margin:0;font-size:2rem}}h2{{margin:0 0 20px;font-size:1.4rem}}h3{{margin:0 0 15px}}p{{color:#c4c8e0;margin:6px 0 0}}.top,.score-grid,.detail-grid{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.panel,.analysis{{background:linear-gradient(135deg,#171e40,#10152f);border:1px solid #545c9b;border-radius:15px;padding:20px;box-shadow:0 12px 35px #03071466}}button,.button{{display:inline-block;background:#42337e;color:#fff;border:1px solid #8876db;border-radius:9px;padding:10px 14px;cursor:pointer;font:inherit;text-decoration:none}}button:hover,.button:hover,button.active{{background:#6145aa}}.refresh{{float:right;font-size:.8rem}}.tabs{{display:flex;gap:8px;margin:18px 0 8px}}.scroll{{overflow-x:auto}}table{{border-collapse:collapse;width:100%;font-size:.85rem}}th,td{{padding:11px 8px;text-align:left;border-bottom:1px solid #303957;white-space:nowrap}}th{{font-weight:500;color:#d0d2e6}}.green{{color:#4ae485;font-weight:700}}.choose{{padding:5px 8px;font-size:.75rem}}.upload-box{{background:linear-gradient(110deg,#ded5ff,#aa91ef);border-radius:13px;padding:20px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#14142c}}.upload-box p{{color:#282441;font-size:.85rem}}#upload{{display:none}}select{{background:#20264c;border:1px solid #7771c7;color:white;padding:9px;border-radius:7px;margin-top:8px;max-width:100%}}.hint,.status,.updated{{font-size:.82rem;color:#b6bad6;margin-top:12px}}.status{{min-height:1.2em}}.analysis{{margin-top:14px}}.analysis-head{{display:flex;justify-content:space-between;gap:10px;margin-bottom:15px}}.analysis-head span{{font-size:.85rem}}.score-grid>div,.detail-grid>section{{border:1px solid #454d82;border-radius:12px;padding:20px;background:#151c3b}}.verdict{{background:linear-gradient(110deg,#155038,#11263b)!important;display:flex;flex-direction:column;justify-content:center}}.verdict strong{{font-size:3rem;text-transform:uppercase;color:#5cf18c}}.verdict.avoid strong{{color:#ff8585}}.verdict.watchlist strong{{color:#ffd66b}}.pillar{{display:grid;grid-template-columns:170px 1fr 35px;gap:10px;align-items:center;margin:8px 0;font-size:.83rem}}.pillar small{{display:block;color:#abb0d1}}.track{{height:12px;border-radius:20px;background:#333b60;overflow:hidden}}.track span{{display:block;height:100%;border-radius:20px;background:linear-gradient(90deg,#48e683,#a5eb69)}}.detail-grid{{margin-top:14px}}.detail-grid section{{overflow:auto}}.warning{{color:#ffd66b}}.verdict{{flex-direction:row!important;align-items:center;justify-content:space-between!important;gap:20px;min-height:180px;background:linear-gradient(110deg,#155b39,#10263d)!important}}.verdict-text{{display:flex;flex-direction:column}}.verdict-text small{{font-size:1.2rem;font-weight:700}}.verdict-text strong{{font-size:clamp(2.3rem,4vw,4rem);letter-spacing:.02em}}.gauge{{position:relative;width:190px;text-align:center;flex:none}}.gauge svg{{width:100%;display:block}}.gauge path{{fill:none;stroke-width:17;stroke-linecap:round}}.gauge-bg{{stroke:#3e5960}}.gauge-value{{stroke:#54ef78}}.gauge-score{{position:absolute;top:48px;width:100%}}.gauge-score b{{color:#64f290;font-size:2rem}}.gauge-score span{{font-size:1rem}}.gauge small{{display:block;color:#e5e9ef;font-size:.8rem}}.trend-chart{{width:100%;height:auto}}.chart-legend{{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.8rem;color:#d8d8ef}}.sales-dot,.profit-dot{{width:11px;height:11px;border-radius:50%;display:inline-block;margin-left:12px}}.sales-dot{{background:#9965ed}}.profit-dot{{background:#72f6a1}}td.good{{color:#5aee8a;font-weight:700}}td.caution{{color:#ffd45d;font-weight:700}}td.bad{{color:#ff747b;font-weight:700}}td.muted{{color:#aab0c9}}button:disabled{{opacity:.6;cursor:wait}}.analysis-loading{{display:flex;align-items:center;justify-content:center;gap:12px;min-height:140px;color:#d8dcf5;font-weight:600}}.spinner{{display:inline-block;width:24px;height:24px;border:3px solid #53608f;border-top-color:#6cf19b;border-radius:50%;animation:spin .8s linear infinite}}@keyframes spin{{to{{transform:rotate(360deg)}}}}.ai-card,.pillar-grid{{border:1px solid #454d82;border-radius:12px;padding:20px;background:#151c3b}}.ai-card p{{color:#e5e8fa;line-height:1.6;font-size:.95rem}}.pillar-grid{{display:grid;grid-template-columns:1fr 1fr;column-gap:30px;margin-top:14px}}@media(max-width:850px){{.top,.score-grid,.detail-grid{{grid-template-columns:1fr}}.upload-box{{flex-wrap:wrap}}.pillar{{grid-template-columns:140px 1fr 30px}}.pillar-grid{{grid-template-columns:1fr}}}}
</style></head><body><script>window.IPO_AI_ENDPOINT = {json.dumps(ai_endpoint)}; window.IPO_CONTEXT = {ipo_context_json};</script>{market_html}<div class="top"><section class="panel"><button id="refresh" class="refresh" type="button">Refresh data</button><h1>IPO Dashboard</h1><p>Track mainboard and SME IPOs with key financials.</p><div class="tabs"><button id="open-tab" class="active">Open IPOs ({len(opened)})</button><button id="recent-tab">Upcoming / Recently Closed ({len(others)})</button></div><div id="open-list">{table(opened)}</div><div id="recent-list" hidden>{table(others)}</div><div class="updated">Last updated {today.strftime('%d %B %Y')}. <span id="refresh-status" role="status"></span></div></section><section class="panel"><h2>Analyze an IPO in Depth</h2><div id="preferences" class="preferences"></div><div class="upload-box"><div><strong>Upload Screener.in Excel</strong><p>On the company's Screener.in page, select Export to Excel and upload the .xlsx file. Examples: <a href="https://www.screener.in/company/JIOFIN/consolidated/" target="_blank" rel="noopener noreferrer">Jio Financial Services</a> · <a href="https://www.screener.in/company/id/1286298/" target="_blank" rel="noopener noreferrer">Shree Siddhivinayak Greentech</a>.</p></div><label class="button" for="upload">↑ Upload Excel</label><input id="upload" type="file" accept=".xlsx,.xls"></div><div id="upload-status" class="status" role="status"></div></section></div><section id="analysis" class="analysis" hidden></section><script src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"></script><script src="analysis.js"></script><script src="refresh.js"></script><script>
for(const [button,list,otherButton,otherList] of [['open-tab','open-list','recent-tab','recent-list'],['recent-tab','recent-list','open-tab','open-list']])document.getElementById(button).addEventListener('click',()=>{{document.getElementById(list).hidden=false;document.getElementById(otherList).hidden=true;document.getElementById(button).classList.add('active');document.getElementById(otherButton).classList.remove('active')}});</script></body></html>'''
